function localRule(area,intent,i){const key=NAMES[area]&&NAMES[area][intent]&&NAMES[area][intent][i],r=key&&CONTRACT_RULES[key];if(!r)throw new Error("측정 계약 누락: "+area+"/"+intent+"/"+i);return r;}
function typeFor(area,intent,i){return localRule(area,intent,i).type;}
function seed(area,intent,name,i,type){
const r=Object.assign({},localRule(area,intent,i));if(type)r.type=type;
return {area,intent,name,type:r.type,goal:r.goal||0,cycle:r.period==="week"?"week":r.period==="month"?"month":r.period==="total"?"total":"day",unit:r.unit||"",step:1,measure:r,reason:en()?r.reasonEn:r.reasonKo,ideal:en()?("A day where "+name.toLowerCase()+" feels natural"):name+(intent==="reduce"?"에 끌려가지 않는 하루":"가 자연스러운 하루")};
}
function cellSeeds(area,intent){return (en()?NAMES_EN:NAMES)[area][intent].map((n,i)=>seed(area,intent,n,i));}
function smartSeeds(rows){return rows.map(row=>({area:row.area,intent:row.intent,name:en()?row.nameEn:row.nameKo,type:row.type,goal:row.goal||0,cycle:row.cycle||"day",unit:row.unit||row.measure.unit||"",step:1,measure:row.measure,reason:en()?row.reasonEn:row.reasonKo,ideal:en()?("A day where "+row.nameEn.toLowerCase()+" feels natural"):"꾸준히 기록하는 하루"}));}
function searchSeeds(q){
q=q.trim().toLowerCase();if(!q)return null;const key=Object.keys(SMART_SEARCH).find(k=>q.includes(k.toLowerCase()));if(key)return smartSeeds(SMART_SEARCH[key]);
const out=[];AREAS.forEach(a=>Object.keys(I).forEach(intent=>cellSeeds(a[0],intent).forEach(s=>{if(s.name.toLowerCase().includes(q))out.push(s);})));return out.slice(0,6);
}
function contractLabel(m){if(!m)return en()?"Needs confirmation":"기준 확인 필요";const input={count:"횟수",amount:"양",duration:"시간",check:"체크",elapsed:"경과",snapshot:"현재값",rating:"점수",milestone:"단계"};const agg={sum:"합계",count:"발생",latest:"최신값",average:"평균",streak:"연속",elapsed:"경과",completion:"완료율"};const period={day:"하루",week:"주",month:"월",event:"매회",total:"전체"};return (input[m.input]||m.input)+" · "+(agg[m.aggregation]||m.aggregation)+" · "+(period[m.period]||m.period);}
